CREATE Proc [dbo].[ReportGRNoWiseReceivingReport] @GRNOId as nvarchar(50), @Login as nvarchar(max), @SId as int AS select @Login as LoginUser,gm.Date,gm.GRNo,v.Vendor,c.Category, i.Item, (Select Unit from unit  where UId=gd.PackageId) as PackingType, gd.TotalPackage,gd.PcsPerPackage, (select DSNo from DemandSheetMaster_Store where DSCOId = (select DSCOId from PurchaseOrderDetail_Store where POId = gd.POId and ItemId = i.ItemId)) as DSNo, gm.Discount, (select PONo from PurchaseOrderMaster_Store where POId = gd.POId) as PONo, v.Address,v.CellNo, Un.Unit as IssuanceType,iu.IssFactor,iu.PurFactor, Uni.Unit as ReceipeType,iu.RecpFactor,UT.Unit as PurchaseUnit,iu.PkFactor, i.ItemCode, (select ParLevel from ItemParLevel where ItemId= i.ItemId and SId = @SId) as ParLevel, isnull((select sum(Qty) from PurchaseOrderDetail_Store where ItemId = i.ItemId and POId = gd.POId),0) as OrderQty, gd.Rate as UnitPrice, gd.Qty as ReceivedQty , gm.[Desc] as Subcategory from GRNMaster gm  inner join GRNDetail gd on gm.GRNId=gd.GRNId inner join Vendor v on v.VId=gm.VId inner join Store s on gm.SId=s.SId inner join Item i on gd.ItemId=i.ItemId inner join Subcategory sc on i.SBId = sc.SBId inner join Category c on sc.CId=c.CId inner join ItemUnit iu on i.ItemId=iu.ItemId inner join Unit Un on iu.IssUnit=Un.UId inner join Unit Uni on iu.RecpUnit=Uni.UId inner join Unit UT on iu.PurUnit=UT.UId left join Split(@GRNOId,',') sp on sp.items =gm.GRNId where i.ItemId=gd.ItemId and gm.SId=@SId group by gm.Date,gm.GRNo,v.Vendor,c.Category,i.Item, gd.PackageId,gd.TotalPackage,gd.PcsPerPackage, gm.Discount,v.Address,v.CellNo, Un.Unit,iu.IssFactor,iu.PurFactor, Uni.Unit,iu.RecpFactor,UT.Unit,iu.PkFactor, i.ItemCode,gd.Qty,gd.Rate,i.ItemId,gd.POId,gm.[Desc] order by i.Item,gm.GRNo asc